"use strict";

// Single-stroke font for G47 engraving previews. Glyphs sit on a 4 x 6 cell
// (baseline y = 0, cap height y = 6) and advance 6 units, so the characters
// keep the proportions of the Haas engraving font without reproducing it.
// Lower-case letters use the capital shapes at 72% height.

const CAP_HEIGHT = 6;
const ADVANCE = 6;
const LOWER_CASE_SCALE = 0.72;

const dot = (x, y) => [[x - 0.2, y], [x + 0.2, y], [x + 0.2, y + 0.4], [x - 0.2, y + 0.4], [x - 0.2, y]];
const ring = [[1, 0], [0, 1], [0, 5], [1, 6], [3, 6], [4, 5], [4, 1], [3, 0], [1, 0]];
const letterS = [[4, 5], [3, 6], [1, 6], [0, 5], [0, 4], [1, 3], [3, 3], [4, 2], [4, 1], [3, 0], [1, 0], [0, 1]];
const bowl = [[0, 0], [0, 6], [3, 6], [4, 5], [4, 4], [3, 3], [0, 3]];

const GLYPHS = {
  A: [[[0, 0], [2, 6], [4, 0]], [[0.8, 2.4], [3.2, 2.4]]],
  B: [[[0, 0], [0, 6], [3, 6], [4, 5], [4, 4], [3, 3], [0, 3]], [[3, 3], [4, 2], [4, 1], [3, 0], [0, 0]]],
  C: [[[4, 5], [3, 6], [1, 6], [0, 5], [0, 1], [1, 0], [3, 0], [4, 1]]],
  D: [[[0, 0], [0, 6], [2.5, 6], [4, 4.5], [4, 1.5], [2.5, 0], [0, 0]]],
  E: [[[4, 6], [0, 6], [0, 0], [4, 0]], [[0, 3], [3, 3]]],
  F: [[[4, 6], [0, 6], [0, 0]], [[0, 3], [3, 3]]],
  G: [[[4, 5], [3, 6], [1, 6], [0, 5], [0, 1], [1, 0], [3, 0], [4, 1], [4, 3], [2, 3]]],
  H: [[[0, 0], [0, 6]], [[4, 0], [4, 6]], [[0, 3], [4, 3]]],
  I: [[[1, 6], [3, 6]], [[2, 6], [2, 0]], [[1, 0], [3, 0]]],
  J: [[[4, 6], [4, 1], [3, 0], [1, 0], [0, 1]]],
  K: [[[0, 0], [0, 6]], [[4, 6], [0, 2]], [[1, 3], [4, 0]]],
  L: [[[0, 6], [0, 0], [4, 0]]],
  M: [[[0, 0], [0, 6], [2, 3], [4, 6], [4, 0]]],
  N: [[[0, 0], [0, 6], [4, 0], [4, 6]]],
  O: [ring],
  P: [bowl],
  Q: [ring, [[2.5, 1.5], [4, -0.5]]],
  R: [bowl, [[2, 3], [4, 0]]],
  S: [letterS],
  T: [[[0, 6], [4, 6]], [[2, 6], [2, 0]]],
  U: [[[0, 6], [0, 1], [1, 0], [3, 0], [4, 1], [4, 6]]],
  V: [[[0, 6], [2, 0], [4, 6]]],
  W: [[[0, 6], [1, 0], [2, 4], [3, 0], [4, 6]]],
  X: [[[0, 0], [4, 6]], [[0, 6], [4, 0]]],
  Y: [[[0, 6], [2, 3], [4, 6]], [[2, 3], [2, 0]]],
  Z: [[[0, 6], [4, 6], [0, 0], [4, 0]]],
  0: [[[1, 0], [0, 1.5], [0, 4.5], [1, 6], [3, 6], [4, 4.5], [4, 1.5], [3, 0], [1, 0]]],
  1: [[[1, 5], [2, 6], [2, 0]], [[1, 0], [3, 0]]],
  2: [[[0, 5], [1, 6], [3, 6], [4, 5], [4, 4], [0, 0], [4, 0]]],
  3: [[[0, 5], [1, 6], [3, 6], [4, 5], [4, 4], [3, 3], [4, 2], [4, 1], [3, 0], [1, 0], [0, 1]], [[1.5, 3], [3, 3]]],
  4: [[[3, 0], [3, 6], [0, 2], [4, 2]]],
  5: [[[4, 6], [0, 6], [0, 3], [3, 3], [4, 2], [4, 1], [3, 0], [1, 0], [0, 1]]],
  6: [[[4, 5], [3, 6], [1, 6], [0, 5], [0, 1], [1, 0], [3, 0], [4, 1], [4, 2], [3, 3], [0, 3]]],
  7: [[[0, 6], [4, 6], [1.5, 0]]],
  8: [[[1, 3], [0, 4], [0, 5], [1, 6], [3, 6], [4, 5], [4, 4], [3, 3], [1, 3], [0, 2], [0, 1], [1, 0], [3, 0], [4, 1], [4, 2], [3, 3]]],
  9: [[[4, 3], [1, 3], [0, 4], [0, 5], [1, 6], [3, 6], [4, 5], [4, 1], [3, 0], [1, 0], [0, 1]]],
  " ": [],
  "-": [[[0.5, 3], [3.5, 3]]],
  ".": [dot(2, 0)],
  ",": [[[2.2, 0.4], [2.2, 0], [1.5, -1]]],
  "/": [[[0, 0], [4, 6]]],
  "\\": [[[0, 6], [4, 0]]],
  ":": [dot(2, 1), dot(2, 4)],
  ";": [dot(2, 4), [[2.2, 1.4], [2.2, 1], [1.5, 0]]],
  "+": [[[2, 1], [2, 5]], [[0, 3], [4, 3]]],
  "=": [[[0, 2], [4, 2]], [[0, 4], [4, 4]]],
  "_": [[[0, -0.5], [4, -0.5]]],
  "#": [[[1, 0], [1, 6]], [[3, 0], [3, 6]], [[0, 2], [4, 2]], [[0, 4], [4, 4]]],
  "(": [[[3, 6], [1.5, 4.5], [1.5, 1.5], [3, 0]]],
  ")": [[[1, 6], [2.5, 4.5], [2.5, 1.5], [1, 0]]],
  "[": [[[3, 6.5], [1.5, 6.5], [1.5, -0.5], [3, -0.5]]],
  "]": [[[1, 6.5], [2.5, 6.5], [2.5, -0.5], [1, -0.5]]],
  "{": [[[3, 6.5], [2, 6], [2, 3.5], [1, 3], [2, 2.5], [2, 0], [3, -0.5]]],
  "}": [[[1, 6.5], [2, 6], [2, 3.5], [3, 3], [2, 2.5], [2, 0], [1, -0.5]]],
  "?": [[[0, 5], [1, 6], [3, 6], [4, 5], [4, 4], [2, 2.5], [2, 1.5]], dot(2, 0)],
  "!": [[[2, 6], [2, 1.5]], dot(2, 0)],
  "'": [[[2, 6], [2, 4.5]]],
  "\"": [[[1.3, 6], [1.3, 4.5]], [[2.7, 6], [2.7, 4.5]]],
  "*": [[[2, 1], [2, 5]], [[0.3, 2], [3.7, 4]], [[0.3, 4], [3.7, 2]]],
  "<": [[[4, 5], [0, 3], [4, 1]]],
  ">": [[[0, 5], [4, 3], [0, 1]]],
  "^": [[[0.5, 4], [2, 6], [3.5, 4]]],
  "~": [[[0, 3], [1, 4], [3, 2], [4, 3]]],
  "|": [[[2, -0.5], [2, 6.5]]],
  "`": [[[1.5, 6], [2.5, 5]]],
  "%": [[[0, 0], [4, 6]], [[0.5, 5], [1, 5.5], [1.5, 5], [1, 4.5], [0.5, 5]], [[2.5, 1], [3, 1.5], [3.5, 1], [3, 0.5], [2.5, 1]]],
  "$": [letterS, [[2, -0.5], [2, 6.5]]],
  "&": [[[4, 0], [1, 4], [1, 5], [2, 6], [3, 5], [3, 4], [0, 2], [0, 1], [1, 0], [2.5, 0], [4, 2]]],
  "@": [[[3, 2], [2, 2], [1.5, 2.5], [1.5, 3.5], [2, 4], [3, 4], [3, 2], [4, 2], [4, 5], [3, 6], [1, 6], [0, 5], [0, 1], [1, 0], [4, 0]]]
};

function glyphFor(character) {
  if (Object.hasOwn(GLYPHS, character)) {
    return { strokes: GLYPHS[character], scale: 1, known: true };
  }
  const upper = character.toUpperCase();
  if (upper !== character && Object.hasOwn(GLYPHS, upper)) {
    return { strokes: GLYPHS[upper], scale: LOWER_CASE_SCALE, known: true };
  }
  return { strokes: GLYPHS["?"], scale: 1, known: false };
}

// Returns engraving strokes (arrays of { x, y }) for `text` starting at the
// lower-left corner (x, y), `height` tall, rotated `angle` degrees CCW.
function strokeText(text, { x = 0, y = 0, height = 1, angle = 0 } = {}) {
  const scale = height / CAP_HEIGHT;
  const radians = (angle * Math.PI) / 180;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const strokes = [];
  const unknown = new Set();
  [...String(text)].forEach((character, index) => {
    const glyph = glyphFor(character);
    if (!glyph.known) {
      unknown.add(character);
    }
    const offset = index * ADVANCE;
    for (const stroke of glyph.strokes) {
      strokes.push(stroke.map(([gx, gy]) => {
        const localX = (offset + gx) * scale;
        const localY = gy * scale * glyph.scale;
        return {
          x: x + localX * cos - localY * sin,
          y: y + localX * sin + localY * cos
        };
      }));
    }
  });
  return { strokes, unknown: [...unknown] };
}

module.exports = {
  CAP_HEIGHT,
  strokeText
};
